17: function escapeHtml(value) {
18:   return String(value).replace(/[&<>'"]/g, character => ({
19:     "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;",
20:   })[character]);
21: }
