23: function shortRepo(url) {
24:   try { return new URL(url).pathname.replace(/^\//, "").replace(/\.git$/, ""); }
25:   catch { return url; }
26: }
27: 
28: function signal(label, value, present = true) {
29:   return `<div class="signal ${present ? "" : "missing"}"><strong>${value}</strong><span>${label}</span></div>`;
30: }
