32: function renderManifest(manifest, score = null) {
33:   activeManifest = manifest;
34:   activeReport = null;
35:   emptyState.classList.add("hidden");
36:   results.classList.remove("hidden");
37:   document.querySelector("#resultRepo").textContent = shortRepo(manifest.source_url);
38:   document.querySelector("#resultSha").textContent = manifest.commit_sha.slice(0, 12);
39:   const calculated = score ?? Math.min(96, 48 + Object.values(manifest.signals).filter(v => v === true).length * 8);
40:   document.querySelector("#resultScore").textContent = calculated;
41:   document.querySelector(".score-ring").style.setProperty("--score", calculated);
42: 
43:   const s = manifest.signals;
44:   document.querySelector("#signalGrid").innerHTML = [
45:     signal("README", s.has_readme ? "FOUND" : "MISS", s.has_readme),
46:     signal("LICENSE", s.has_license ? "FOUND" : "MISS", s.has_license),
47:     signal("TESTS", s.has_tests ? "FOUND" : "MISS", s.has_tests),
48:     signal("CI", s.has_ci ? "FOUND" : "MISS", s.has_ci),
49:     signal("FILES", String(manifest.file_count), true),
50:   ].join("");
51: 
52:   const docs = manifest.documents.slice(0, 12);
53:   document.querySelector("#evidenceCount").textContent = `${manifest.documents.length} 份已采集文档`;
54:   document.querySelector("#evidenceList").innerHTML = docs.map(doc =>
55:     `<div class="evidence-item"><code>${escapeHtml(doc.path)}</code><span>${Number(doc.line_count)} lines</span></div>`
56:   ).join("");
57:   const warning = manifest.warnings.length
58:     ? manifest.warnings.join(" ")
59:     : "快照基础检查未发现缺失的核心项目元数据；语义结论仍需生成报告后评估。";
60:   document.querySelector("#resultCallout").textContent = warning;
61:   document.querySelector("#reportView").classList.add("hidden");
62:   document.querySelector("#scoreBreakdown").classList.add("hidden");
63:   generateButton.classList.remove("hidden");
64: }
65: 
66: function evidenceLabel(item) {
67:   const ref = item.evidence?.[0];
68:   return ref ? `${ref.path}:${Number(ref.line_start)}-${Number(ref.line_end)}` : "NO EVIDENCE";
69: }
