71: function renderReport(report) {
72:   activeReport = report;
73:   const view = document.querySelector("#reportView");
74:   view.classList.remove("hidden");
75:   document.querySelector("#reportDecision").textContent = report.decision.replaceAll("_", " ");
76:   document.querySelector("#reportSummary").textContent = report.executive_summary;
77:   document.querySelector("#claimCount").textContent = `${report.claims.length} 条`;
78:   document.querySelector("#claimList").innerHTML = report.claims.slice(0, 5).map(claim =>
79:     `<article class="report-card"><strong>${escapeHtml(claim.id)} · ${escapeHtml(claim.category)}</strong><p>${escapeHtml(claim.text)}</p><code>${escapeHtml(evidenceLabel(claim))}</code></article>`
80:   ).join("");
81:   const risks = [...report.risks, ...(report.unknowns || []).map((text, index) => ({
82:     id: `U${String(index + 1).padStart(3, "0")}`, severity: "unknown", title: "待确认", description: text, evidence: [],
83:   }))];
84:   document.querySelector("#riskCount").textContent = `${risks.length} 项`;
85:   document.querySelector("#riskList").innerHTML = risks.slice(0, 6).map(risk =>
86:     `<article class="report-card risk-${escapeHtml(risk.severity)}"><strong>${escapeHtml(risk.id)} · ${escapeHtml(risk.title)}</strong><p>${escapeHtml(risk.description)}</p><code>${escapeHtml(evidenceLabel(risk))}</code></article>`
87:   ).join("");
88:   view.scrollIntoView({behavior: "smooth", block: "nearest"});
89: }
