91: function renderEvaluation(evaluation) {
92:   document.querySelector("#scoreBreakdown").classList.remove("hidden");
93:   document.querySelector("#gradeLabel").textContent = `Grade ${evaluation.grade}`;
94:   document.querySelector("#dimensionList").innerHTML = evaluation.dimensions.map(item =>
95:     `<div class="dimension-row"><span>${escapeHtml(item.label)}</span><div class="dimension-bar"><i style="width:${Math.max(0, Math.min(100, Number(item.score) / 4 * 100))}%"></i></div><strong>${Number(item.score).toFixed(1)}</strong></div>`
96:   ).join("");
97:   document.querySelector("#resultScore").textContent = Math.round(evaluation.total_score);
98:   document.querySelector(".score-ring").style.setProperty("--score", evaluation.total_score);
99:   if (evaluation.hard_failures.length) {
100:     document.querySelector("#resultCallout").textContent = `硬门槛触发：${evaluation.hard_failures.join(" ")}`;
101:   }
102: }
